// Production inventory-only investigation. SELECT statements only; no customer fields.
import {execFileSync} from 'node:child_process'
const db='orders_db_prod'
function read(sql) {
  if (!/^\s*(SELECT|WITH)\b/i.test(sql) || /;\s*\S/.test(sql) ||
      /\b(UPDATE|DELETE|INSERT|REPLACE|DROP|ALTER|ATTACH|PRAGMA|VACUUM)\b/i.test(sql)) throw Error('READ-ONLY SQL required')
  const raw=execFileSync('npx',['wrangler','d1','execute',db,'--remote','--config','wrangler.jsonc','--command='+sql,'--json'],
    {encoding:'utf8',maxBuffer:10*1024*1024,timeout:75000})
  const page=JSON.parse(raw)
  if(!Array.isArray(page)||!page[0]||page[0].success!==true||!Array.isArray(page[0].results))throw Error('D1 query failure')
  return page[0].results
}
function emit(name,sql){const rows=read(sql);console.log(name,JSON.stringify(rows));return rows}
console.log('AUDIT_MODE=PRODUCTION_READ_ONLY_NO_CUSTOMERS')
const base="WITH ar AS (SELECT inventory_source,variant_id,COUNT(*) AS reservations,SUM(quantity) AS qty FROM inventory_reservations WHERE status='active' GROUP BY inventory_source,variant_id), rows AS (SELECT s.id AS stock_id,s.inventory_source AS source,s.variant_id,s.quantity AS physical,s.reserved_quantity AS cached_reserved,COALESCE(ar.qty,0) AS active_reserved,COALESCE(ar.reservations,0) AS reservation_rows,s.quantity-COALESCE(ar.qty,0) AS available,COALESCE(p.name,'Unlinked variant') AS product,v.color,v.size_label AS size,v.material,v.length,v.is_active AS variant_active,p.is_active AS product_active,s.updated_at FROM inventory_stock s LEFT JOIN ar ON ar.inventory_source=s.inventory_source AND ar.variant_id=s.variant_id LEFT JOIN catalog_variants v ON v.id=s.variant_id LEFT JOIN catalog_products p ON p.id=v.product_id) "
emit('STOCK_COUNTS',base+"SELECT source,COUNT(*) AS sku_rows,SUM(CASE WHEN physical<0 THEN 1 ELSE 0 END) AS negative_physical_skus,SUM(CASE WHEN physical<0 THEN -physical ELSE 0 END) AS negative_physical_units,SUM(CASE WHEN available<0 THEN 1 ELSE 0 END) AS deficit_skus,SUM(CASE WHEN available<0 THEN -available ELSE 0 END) AS deficit_units,SUM(CASE WHEN cached_reserved<>active_reserved THEN 1 ELSE 0 END) AS reserved_mismatch_skus,SUM(CASE WHEN cached_reserved<>active_reserved THEN ABS(cached_reserved-active_reserved) ELSE 0 END) AS mismatch_units,SUM(CASE WHEN variant_id IS NULL OR variant_active IS NULL THEN 1 ELSE 0 END) AS orphan_stock,SUM(CASE WHEN variant_active=0 OR product_active=0 THEN 1 ELSE 0 END) AS inactive_skus,SUM(physical) AS physical_units,SUM(cached_reserved) AS cached_reserved_units,SUM(active_reserved) AS active_reserved_units FROM rows GROUP BY source ORDER BY source")
const deficit=emit('TOP_DEFICITS',base+"SELECT stock_id,source,variant_id,product,color,size,material,length,physical,cached_reserved,active_reserved,available,reservation_rows,variant_active,product_active,updated_at FROM rows WHERE available<0 OR physical<0 ORDER BY CASE WHEN available<0 THEN -available ELSE 0 END DESC,physical ASC LIMIT 35")
emit('RESERVATION_MISMATCH',base+"SELECT stock_id,source,variant_id,product,color,size,physical,cached_reserved,active_reserved,available,reservation_rows FROM rows WHERE cached_reserved<>active_reserved ORDER BY ABS(cached_reserved-active_reserved) DESC LIMIT 30")
emit('ACTIVE_RESERVATIONS_MISSING_STOCK',"SELECT r.inventory_source AS source,r.variant_id,COUNT(*) AS n,SUM(r.quantity) AS reserved,MAX(p.name) AS product,MAX(v.color) AS color,MAX(v.size_label) AS size FROM inventory_reservations r LEFT JOIN inventory_stock s ON s.inventory_source=r.inventory_source AND s.variant_id=r.variant_id LEFT JOIN catalog_variants v ON v.id=r.variant_id LEFT JOIN catalog_products p ON p.id=v.product_id WHERE r.status='active' AND s.id IS NULL GROUP BY r.inventory_source,r.variant_id ORDER BY reserved DESC LIMIT 25")
emit('ACTIVE_RESERVATION_ORDER_STATES',"SELECT COALESCE(o.order_status,'missing_order') AS order_status,COALESCE(o.shipping_status,'unknown') AS shipping_status,COUNT(*) AS reservation_rows,SUM(r.quantity) AS units FROM inventory_reservations r LEFT JOIN orders o ON o.id=r.order_id WHERE r.status='active' GROUP BY o.order_status,o.shipping_status ORDER BY units DESC LIMIT 30")
emit('ACTIVE_ORDER_ITEMS_NO_RESERVATION',"SELECT COALESCE(oi.stock_writeoff_status,'unknown') AS writeoff_state,COALESCE(oi.is_workshop,0) AS is_workshop,COUNT(*) AS item_count,SUM(oi.quantity) AS units FROM order_items oi JOIN orders o ON o.id=oi.order_id WHERE o.order_status='active' AND COALESCE(o.shipping_status,'not_sent')<>'sent' AND oi.quantity>0 AND oi.variant_id IS NOT NULL AND NOT EXISTS (SELECT 1 FROM inventory_reservations r WHERE r.order_item_id=oi.id AND r.status='active') GROUP BY oi.stock_writeoff_status,oi.is_workshop ORDER BY item_count DESC")
emit('STOCK_CHECKS',"SELECT inventory_source AS source,COUNT(*) AS checks,SUM(CASE WHEN difference_quantity<>0 THEN 1 ELSE 0 END) AS differing_checks,SUM(CASE WHEN difference_quantity<0 THEN 1 ELSE 0 END) AS fewer_checks,SUM(CASE WHEN difference_quantity>0 THEN 1 ELSE 0 END) AS more_checks,MAX(checked_at) AS last_check FROM inventory_stock_checks GROUP BY inventory_source")
emit('RECENT_MOVEMENT_TYPES',"SELECT inventory_source AS source,movement_type,reference_type,COUNT(*) AS operations,SUM(quantity_delta) AS net_qty,MAX(created_at) AS last_at FROM inventory_movements WHERE created_at>='2026-09-01' GROUP BY inventory_source,movement_type,reference_type ORDER BY operations DESC LIMIT 40")
emit('LIFECYCLE_SUMMARY',"SELECT inventory_source AS source,event_type,status,COUNT(*) AS n,SUM(quantity) AS units FROM inventory_lifecycle_events GROUP BY inventory_source,event_type,status ORDER BY n DESC LIMIT 35")
emit('ACTIVE_SKU_DUPLICATES',"SELECT p.name AS product,v.color,v.size_label AS size,v.material,v.length,COUNT(DISTINCT v.id) AS variants,GROUP_CONCAT(DISTINCT v.id) AS ids,SUM(COALESCE(s.quantity,0)) AS physical FROM catalog_variants v JOIN catalog_products p ON p.id=v.product_id LEFT JOIN inventory_stock s ON s.variant_id=v.id WHERE v.is_active=1 AND p.is_active=1 GROUP BY v.product_id,v.color,v.size_label,v.material,v.length HAVING COUNT(DISTINCT v.id)>1 ORDER BY variants DESC LIMIT 22")
const sample=deficit.slice(0,12).filter(x=>Number.isSafeInteger(x.variant_id)&&['warehouse','boutique'].includes(x.source))
if(sample.length){
 const conditions=sample.map(x=>"(inventory_source='"+x.source+"' AND variant_id="+x.variant_id+")").join(' OR ')
 emit('DEFICIT_VARIANT_MOVEMENTS',"SELECT inventory_source AS source,variant_id,id,movement_type,quantity_delta,quantity_after,reference_type,created_at FROM inventory_movements WHERE ("+conditions+") AND created_at>='2026-09-01' ORDER BY created_at DESC,id DESC LIMIT 110")
 const cond2=conditions.replaceAll('inventory_source','r.inventory_source').replaceAll('variant_id','r.variant_id')
 emit('DEFICIT_VARIANT_RESERVATIONS',"SELECT r.inventory_source AS source,r.variant_id,r.id AS reservation_id,r.order_id,r.quantity,r.status,r.created_at,r.updated_at,o.order_status,o.shipping_status,oi.stock_writeoff_status FROM inventory_reservations r LEFT JOIN orders o ON o.id=r.order_id LEFT JOIN order_items oi ON oi.id=r.order_item_id WHERE r.status='active' AND ("+cond2+") ORDER BY r.variant_id,r.created_at DESC LIMIT 85")
}
console.log('AUDIT_FINISHED_READ_ONLY')